action.command:
node -e "
const fs = require('fs');
const path = require('path');
const chunks = [];
process.stdin.on('data', d => chunks.push(d));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(Buffer.concat(chunks).toString());
    const prompt = (input.userPrompt || '').toLowerCase();

    const configPath = path.join(process.cwd(), '.kiro', 'agentpicker.json');
    const configFile = fs.readFileSync(configPath, 'utf8');
    const agentsData = JSON.parse(configFile).agents || {};

    let detected = null;

    for (const [key, value] of Object.entries(agentsData)) {
      const desc = (value.description || '').toLowerCase();
      const marker = 'task involves:';
      const markerIndex = desc.indexOf(marker);

      if (markerIndex !== -1) {
        const keywordSection = desc.substring(markerIndex + marker.length);
        const keywords = keywordSection
          .split(',')
          .map(k => k.replace(/[.\s]+/g, ' ').trim())
          .filter(k => k.length > 0);

        if (keywords.some(k => prompt.includes(k))) {
          detected = {
            category: key.toUpperCase().replace(/-agent$/i, ''),
            agent: value.name,
            model: value.model
          };
          break;
        }
      }
    }

    if (detected) {
      process.stdout.write(
        '[Phase Observer] Routing Category: ' + detected.category +
        ' | Agent: ' + detected.agent +
        ' | Model: ' + detected.model + '\n' +
        'Tip: Use @TravelPlatform Router for automatic phase detection and model selection.\n'
      );
    }
    process.exit(0);
  } catch(e) {
    process.exit(0);
  }
});
"
